package com.primehr.migration;
import org.flywaydb.core.Flyway; import org.flywaydb.core.api.MigrationVersion; import org.junit.jupiter.api.Test; import java.sql.DriverManager; import java.util.*; import static org.assertj.core.api.Assertions.assertThat;
class PrimeHrV46ToV47UpgradeTest {
 @Test void populatedAwardsSurviveSuccessionFoundationMigration()throws Exception{String db="primehr_v47_"+UUID.randomUUID().toString().replace("-","");String url="jdbc:h2:mem:"+db+";MODE=PostgreSQL;DB_CLOSE_DELAY=-1";Map<String,String> p=Map.of("primehrSchema","PUBLIC");Flyway initial=flyway(url,p,"46");initial.migrate();try{try(var c=DriverManager.getConnection(url,"sa","");var s=c.createStatement()){s.executeUpdate("INSERT INTO PUBLIC.rr_governance_policy(id,agency_id,code,normalized_code,created_by,created_at,updated_by,updated_at) VALUES('policy','A','PRAISE','PRAISE','test',CURRENT_TIMESTAMP,'test',CURRENT_TIMESTAMP)");}Flyway upgraded=flyway(url,p,"47");upgraded.migrate();assertThat(upgraded.info().current().getVersion().getVersion()).isEqualTo("47");try(var c=DriverManager.getConnection(url,"sa","");var r=c.createStatement().executeQuery("SELECT COUNT(*) FROM PUBLIC.rr_governance_policy WHERE id='policy'")){r.next();assertThat(r.getLong(1)).isOne();}try(var c=DriverManager.getConnection(url,"sa","");var r=c.createStatement().executeQuery("SELECT COUNT(*) FROM PUBLIC.succession_governance_policy")){r.next();assertThat(r.getLong(1)).isZero();}}finally{initial.clean();}}
 private Flyway flyway(String url,Map<String,String>p,String target){return Flyway.configure().dataSource(url,"sa","").locations("classpath:db/migration/postgresql").schemas("PUBLIC").defaultSchema("PUBLIC").placeholders(p).target(MigrationVersion.fromVersion(target)).cleanDisabled(false).load();}
}
